 "content": "def transform(grid):
    """Connect every pair of 5 markers sharing a row or column with 3s."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for r in range(h):
        cols = [c for c, v in enumerate(grid[r]) if v == 5]
        for a, b in zip(cols, cols[1:]):
            for c in range(a + 1, b):
                out[r][c] = 3
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == 5]
        for a, b in zip(rows, rows[1:]):
            for r in range(a + 1, b):
                out[r][c] = 3
    return out
